const fs = require('fs');

function applyFromFile(listFile, tagNames) {
  const content = fs.readFileSync(listFile, 'utf8');
  const lines = content.split('\n');
  let count = 0;
  for (const line of lines) {
    const m = line.match(/^\s+(\S+\.(?:ts|html)):(\d+)\s+<([^>]+)>/);
    if (!m) continue;
    const file = m[1].replace(/\\/g, '/');
    const lineNo = parseInt(m[2], 10);
    const tag = m[3];
    if (!tagNames.includes(tag)) continue;
    const fileLines = fs.readFileSync(file, 'utf8').split('\n');
    const idx = lineNo - 1;
    if (!fileLines[idx].includes('disableTooltip')) {
      console.log('SKIP (no match)', file, lineNo, fileLines[idx]);
      continue;
    }
    fileLines[idx] = fileLines[idx].replace(/disableTooltip/g, 'hideHint');
    fs.writeFileSync(file, fileLines.join('\n'));
    count++;
  }
  console.log(listFile, 'applied', count);
}

