    selector: "app-feature-11",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent ],
    templateUrl: "./feature-11.component.html"
})
export class Feature011Component {
    isActive = false;
    count = 4;
    title = "Title 11";
    statusVariant: PillVariant = "success";
    items: { id: number; name: string; variant: PillVariant; hidden: boolean }[] = [ { id: 1, name: "Alpha", variant: "info", hidden: false }, { id: 2, name: "Beta", variant: "warning", hidden: false } ];
    user?: { prefs?: { quiet: boolean } } = { prefs: { quiet: true } };
    flags: Record<string, boolean> = { hidden: false };

    isHidden(): boolean {
        return this.count > 4;
    }

    readonly firstPill = viewChild(PillComponent);
    readonly hintHidden = computed(() => this.firstPill()?.disableTooltip() ?? false);
}

