const fs = require('fs');

const content = fs.readFileSync('C:/Users/rafal/AppData/Local/Temp/signal-reads.txt', 'utf8');
const lines = content.split('\n').filter(Boolean);
let renamed = 0, skipped = 0;
for (const entry of lines) {
  const m = entry.match(/^([^:]+):(\d+):(.*)$/);
  if (!m) { console.log('NOMATCH', entry); continue; }
  const file = m[1];
  const lineNo = parseInt(m[2], 10);
  const text = m[3];
  const leaveCard = /summary\.disableTooltip\(\)/.test(text) || /card\(\)\?\.disableTooltip\(\)/.test(text);
  if (leaveCard) { skipped++; continue; }
  const fileLines = fs.readFileSync(file, 'utf8').split('\n');
  const idx = lineNo - 1;
  if (!fileLines[idx].includes('.disableTooltip()')) {
    console.log('SKIP (mismatch)', file, lineNo, fileLines[idx]);
    continue;
  }
  fileLines[idx] = fileLines[idx].split('.disableTooltip()').join('.hideHint()');
  fs.writeFileSync(file, fileLines.join('\n'));
  renamed++;
}
console.log('renamed', renamed, 'skipped(card)', skipped);

